def check_rules(R):
    S = list(range(1, 192))
    # Rule 1: x in R => 2x in R (if 2x <= 191)
    for x in R:
        if 2*x <= 191 and 2*x not in R:
            return False
    # Rule 2: x, y in R => x+y in R (if x+y <= 191)
    for x in R:
        for y in R:
            if x+y <= 191 and x+y not in R:
                return False
    return True

R1 = [i for i in range(2, 192, 2)]
print(f"R1 valid: {check_rules(R1)}, size: {len(R1)}, sum K: {sum(i for i in range(1, 192) if i not in R1)}")
R2 = [i for i in range(97, 192)]
print(f"R2 valid: {check_rules(R2)}, size: {len(R2)}, sum K: {sum(i for i in range(1, 192) if i not in R2)}")
